<template><div class="page"><h1>实时故障注入与自动诊断</h1><p>覆盖动力和控制系统；到达注入时刻后执行告警、诊断、隔离、评估，也可人工清除故障并验证恢复。</p><el-card><el-form inline><el-form-item label="子系统"><el-select v-model="form.subsystem" @change="form.fault_mode=options[form.subsystem]?.[0]"><el-option v-for="(_,s) in options" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="故障"><el-select v-model="form.fault_mode"><el-option v-for="m in options[form.subsystem]||[]" :key="m" :label="m" :value="m"/></el-select></el-form-item><el-form-item label="注入时间"><el-input-number v-model="form.injection_time" :min="1"/></el-form-item><el-form-item label="严重度"><el-slider v-model="form.severity" :min=".1" :max="1" :step=".1"/></el-form-item><el-button type="primary" @click="start" :loading="loading">创建任务</el-button><el-button :disabled="!task" @click="toggle">{{playing?'暂停':'开始播放'}}</el-button><el-button type="warning" plain :disabled="!task||!latest?.injected" @click="clearFault">清除故障并恢复</el-button></el-form></el-card><el-card v-if="task" class="result"><div class="status"><el-tag>{{stageLabels[task.current_stage]||task.current_stage}}</el-tag><b>时间戳 {{time}}</b><span>注入时刻 {{task.injection_time}}</span></div><el-steps :active="active" finish-status="success" simple><el-step v-for="s in stages" :key="s" :title="s"/></el-steps><el-alert v-if="latest?.clearance?.restored" title="故障已清除，遥测恢复正常监测范围" type="success"/><el-alert v-else-if="latest" :title="latest.alarm.triggered?`检测到 ${latest.diagnosis.fault}`:'当前运行正常'" :type="latest.alarm.triggered?'error':'success'"/><el-descriptions v-if="latest" border :column="3"><el-descriptions-item label="告警信号">{{signalLabels[latest.alarm.signal]||latest.alarm.signal}}</el-descriptions-item><el-descriptions-item label="诊断置信度">{{latest.diagnosis.confidence}}</el-descriptions-item><el-descriptions-item label="隔离对象">{{latest.isolation.target||'—'}}</el-descriptions-item><el-descriptions-item label="健康指数">{{latest.health.component_hi.toFixed(4)}}</el-descriptions-item><el-descriptions-item label="剩余寿命（RUL）">{{latest.rul.value??'—'}}</el-descriptions-item><el-descriptions-item label="消息">{{latest.notification.message}}</el-descriptions-item></el-descriptions><ReportChart :option="chart"/><el-table :data="rows.slice(-15).reverse()"><el-table-column prop="time" label="时间"/><el-table-column prop="pressure" label="压力"/><el-table-column prop="temperature" label="温度"/><el-table-column prop="bus_voltage" label="母线电压"/><el-table-column prop="battery_capacity" label="电池容量"/><el-table-column prop="attitude_error" label="姿态误差"/><el-table-column prop="HI_norm" label="健康指数"/></el-table></el-card></div></template>
<script setup>import{ref,computed,onUnmounted,onMounted}from'vue';import{ElMessage}from'element-plus';import ReportChart from'../components/ReportChart.vue';const options=ref({}),loading=ref(false),playing=ref(false),task=ref(null),latest=ref(null),rows=ref([]),time=ref(0),stages=['监测','注入','告警','诊断','隔离','健康评估','RUL','发布'],stageLabels={ready:'准备就绪',monitoring:'监测中',injected:'已注入',alarm:'告警',diagnosis:'诊断',isolation:'隔离',health:'健康评估',rul:'寿命预测',published:'已发布',cleared:'已清除'},signalLabels={pressure:'压力',temperature:'温度',bus_voltage:'母线电压',battery_capacity:'电池容量',attitude_error:'姿态误差',control_error:'控制误差',HI_norm:'健康指数'},form=ref({subsystem:'动力',fault_mode:'泄漏',severity:.8,injection_time:10});let timer;const active=computed(()=>latest.value?.notification.published?8:latest.value?.injected?2:1);const chart=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['压力','母线电压','健康指数']},xAxis:{type:'value'},yAxis:{type:'value',scale:true},series:[{name:'压力',type:'line',data:rows.value.map(x=>[x.time,x.pressure])},{name:'母线电压',type:'line',data:rows.value.map(x=>[x.time,x.bus_voltage])},{name:'健康指数',type:'line',data:rows.value.map(x=>[x.time,x.HI_norm])}]}));onMounted(async()=>options.value=(await(await fetch('/api/v1/simulation-demo/sample/')).json()).subsystems);async function start(){loading.value=true;try{const r=await fetch('/api/v1/simulation-demo/workflows/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form.value,mode:'realtime'})});const j=await r.json();if(!r.ok)throw Error(j.error);task.value=j.task;latest.value=null;rows.value=[];time.value=0}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function send(extra={}){const values={pressure:1+Math.sin(time.value/5)*.01,temperature:.4+Math.sin(time.value/8)*.01,bus_voltage:1,battery_capacity:1,attitude_error:0,control_error:.02};const r=await fetch(`/api/v1/simulation-demo/workflows/${task.value.id}/samples/`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({timestamp:time.value,values,...extra})});const j=await r.json();if(!r.ok)throw Error(j.error);task.value.current_stage=j.event.stage;latest.value=j.event.result;rows.value.push(j.event.sample);time.value++}async function tick(){if(!playing.value)return;try{await send();timer=setTimeout(tick,500)}catch(e){playing.value=false;ElMessage.error(e.message)}}async function clearFault(){playing.value=false;clearTimeout(timer);try{await send({clear_fault:true});ElMessage.success('故障已清除并恢复正常信号')}catch(e){ElMessage.error(e.message)}}function toggle(){playing.value=!playing.value;clearTimeout(timer);if(playing.value)tick()}onUnmounted(()=>clearTimeout(timer))</script>
<style scoped>.page{max-width:1400px}.page>p{color:#67788e}.el-select{width:150px}.el-slider{width:140px}.result{margin-top:18px}.status{display:flex;gap:18px;align-items:center;margin-bottom:16px}.el-steps,.el-alert,.el-descriptions{margin-bottom:18px}</style>
